<?php
require_once __DIR__.'/_header.php';require_admin();$page_title='Volunteer Network';
$statuses=['PENDING','ACTIVE','INACTIVE','ARCHIVED'];
if(isset($_GET['status'],$_GET['id'])&&in_array($_GET['status'],$statuses,true)){$s=db()->prepare('UPDATE volunteers SET status=?,reviewed_by=?,reviewed_at=NOW() WHERE id=?');$s->execute([$_GET['status'],user()['id'],(int)$_GET['id']]);log_admin_activity('update_volunteer_status',$_GET['id'].' '.$_GET['status']);flash('success','Volunteer status updated.');redirect('/admin/volunteers.php');}
$q=trim($_GET['q']??'');$type=trim($_GET['type']??'');$availability=trim($_GET['availability']??'');$where='WHERE status<>"ARCHIVED"';$params=[];if($q!==''){$where.=' AND (full_name LIKE ? OR email LIKE ? OR phone LIKE ? OR location LIKE ? OR emergency_contact_name LIKE ? OR emergency_contact_phone LIKE ?)';for($i=0;$i<6;$i++)$params[]="%$q%";}if($type!==''){$where.=' AND volunteer_type=?';$params[]=$type;}if($availability!==''){$where.=' AND availability=?';$params[]=$availability;}$s=db()->prepare("SELECT * FROM volunteers $where ORDER BY FIELD(status,'PENDING','ACTIVE','INACTIVE'),created_at DESC");$s->execute($params);$volunteers=$s->fetchAll();$types=['Medical volunteer','Driver','Search & rescue','Food distribution','Shelter volunteer','Translator','Drone operator','Engineer','IT volunteer','Blood donor'];
?><style>.volunteer-toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}.volunteer-toolbar input,.volunteer-toolbar select{padding:11px;border:1px solid #cfc8bf;border-radius:7px;font:inherit}.volunteer-list{display:grid;gap:16px}.volunteer-card{background:#fff;border:1px solid #ddd8d0;border-radius:12px;padding:22px}.volunteer-card h2{margin:0 0 8px;font-size:24px}.volunteer-meta{display:flex;flex-wrap:wrap;gap:8px 18px;color:#566;font-size:14px;margin-bottom:16px}.volunteer-meta strong{color:#17202a}.volunteer-details{border-top:1px solid #eee;padding-top:14px;color:#555;line-height:1.7}.volunteer-details p{margin:5px 0}.status{display:inline-block;padding:5px 9px;border-radius:999px;font-size:12px;font-weight:700}.pending{background:#f7e4c2;color:#764d00}.active{background:#d9eedf;color:#17602c}.inactive{background:#eee;color:#566}.volunteer-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}</style><div class="content"><form class="volunteer-toolbar"><input name="q" value="<?=e($q)?>" placeholder="Search name, phone, location"><select name="type"><option value="">All volunteer roles</option><?php foreach($types as $item):?><option value="<?=e($item)?>" <?=$type===$item?'selected':''?>><?=e($item)?></option><?php endforeach;?></select><select name="availability"><option value="">All availability</option><option value="AVAILABLE" <?=$availability==='AVAILABLE'?'selected':''?>>Available now</option><option value="ON_CALL" <?=$availability==='ON_CALL'?'selected':''?>>On call</option><option value="UNAVAILABLE" <?=$availability==='UNAVAILABLE'?'selected':''?>>Unavailable</option></select><button>Filter</button></form><div class="volunteer-list"><?php foreach($volunteers as $volunteer):?><article class="volunteer-card"><span class="status <?=strtolower($volunteer['status'])?>"><?=e($volunteer['status'])?></span><h2><?=e($volunteer['full_name'])?></h2><div class="volunteer-meta"><span><strong>Role:</strong> <?=e($volunteer['volunteer_type'])?></span><span><strong>Availability:</strong> <?=e(str_replace('_',' ',$volunteer['availability']))?></span><span><strong>Location:</strong> <?=e($volunteer['location'])?></span><span><strong>Phone:</strong> <?=e($volunteer['phone'])?></span><span><strong>Email:</strong> <?=e($volunteer['email'])?></span></div><div class="volunteer-details"><p><strong>Emergency contact:</strong> <?=e($volunteer['emergency_contact_name'])?> · <?=e($volunteer['emergency_contact_phone'])?></p><?php if($volunteer['languages']):?><p><strong>Languages:</strong> <?=e($volunteer['languages'])?></p><?php endif;?><?php if($volunteer['blood_type']):?><p><strong>Blood type:</strong> <?=e($volunteer['blood_type'])?><?php if($volunteer['last_donation_date']):?> · Last donation: <?=e($volunteer['last_donation_date'])?><?php endif;?></p><?php endif;?><?php if($volunteer['role_details']):?><p><strong>Role details:</strong> <?=e($volunteer['role_details'])?></p><?php endif;?><?php if($volunteer['skills']):?><p><strong>Skills:</strong> <?=e($volunteer['skills'])?></p><?php endif;?></div><?php if($volunteer['status']!=='ARCHIVED'):?><div class="volunteer-actions"><?php if($volunteer['status']!=='ACTIVE'):?><a class="btn" href="?id=<?=$volunteer['id']?>&status=ACTIVE">Mark active</a><?php endif;?><?php if($volunteer['status']!=='INACTIVE'):?><a class="btn secondary" href="?id=<?=$volunteer['id']?>&status=INACTIVE">Mark inactive</a><?php endif;?><a class="btn danger" data-confirm="Archive this volunteer?" href="?id=<?=$volunteer['id']?>&status=ARCHIVED">Archive</a></div><?php endif;?></article><?php endforeach;?><?php if(!$volunteers):?><div class="card">No volunteers match the selected filters.</div><?php endif;?></div></div> 
